def _authorize(
    permission_hook: Any,
    *,
    principal: Any,
    request: Request,
    entity: Optional[dict[str, Any]],
    action: str,
) -> None:
    if permission_hook is None:
        return
    allowed = permission_hook(
        principal=principal,
        request=request,
        entity=entity,
        action=action,
    )
    if allowed is False:
        raise HTTPException(status_code=403, detail="FilterX action is not permitted.")


def _apply_predicates(
    query: Any,
    *,
    predicate_hooks: Iterable[Any],
    principal: Any,
    request: Request,
    entity: dict[str, Any],
    model: type[Any],
    action: str,
) -> Any:
    for hook in predicate_hooks:
        expression = hook(
            principal=principal,
            request=request,
            entity=entity,
            model=model,
            action=action,
        )
        if expression is not None:
            query = query.filter(expression)
    return query


def _normalize_prefix(api_prefix: str) -> str:
    prefix = api_prefix.strip() or "/api"
    if not prefix.startswith("/"):
        prefix = f"/{prefix}"
    if prefix != "/":
        prefix = prefix.rstrip("/")
    else:
        prefix = ""
    return prefix


def _singularize(value: str) -> str:
    lowered = value.strip().lower().replace("-", "_")
    if lowered.endswith("ies") and len(lowered) > 3:
        return lowered[:-3] + "y"
    if lowered.endswith("s") and len(lowered) > 1:
        return lowered[:-1]
    return lowered


def _entity_keys(entity: dict[str, Any]) -> set[str]:
    model = str(entity.get("model") or "")
    table = str(entity.get("table") or "")
    keys = {
        model.lower(),
        table.lower(),
        model.lower().replace("_", "-"),
        table.lower().replace("_", "-"),
        _singularize(model),
        _singularize(table),
        _singularize(model).replace("_", "-"),
        _singularize(table).replace("_", "-"),
    }
    return {key for key in keys if key}


def _build_registry(entities: Iterable[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    registry: dict[str, dict[str, Any]] = {}
    for entity in entities:
        for key in _entity_keys(entity):
            registry[key] = entity
    return registry


def _get_entity(registry: dict[str, dict[str, Any]], raw_name: str) -> dict[str, Any]:
    key = raw_name.strip().lower().replace("-", "_")
    entity = registry.get(key) or registry.get(raw_name.strip().lower())
    if entity is None:
