    return entity


def _model_for_entity(entity: dict[str, Any]) -> type[Any]:
    module_name = entity.get("module")
    model_name = entity.get("model")
    if not module_name or not model_name:
        raise HTTPException(status_code=500, detail=f"Entity metadata for {model_name!r} is missing module/model.")
    module = importlib.import_module(str(module_name))
    return getattr(module, str(model_name))


def _parse_scalar(value: str) -> Any:
    lowered = value.lower()
    if lowered == "true":
        return True
    if lowered == "false":
        return False
    if lowered == "null":
        return None
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        return value


def _parse_value(value: str, operation: str) -> Any:
    if operation in {"in", "not_in"}:
        return [_parse_scalar(item.strip()) for item in value.split(",") if item.strip()]
    if operation == "between":
        parts = [item.strip() for item in value.split(",")]
        if len(parts) != 2:
            raise HTTPException(status_code=400, detail="Operation 'between' requires two comma-separated values.")
        return [_parse_scalar(parts[0]), _parse_scalar(parts[1])]
    return _parse_scalar(value)


def _parse_filter_param(key: str, value: str) -> Optional[dict[str, Any]]:
    for op in sorted(VALID_OPS, key=len, reverse=True):
        suffix = f"_{op}"
        if key.endswith(suffix):
            field = key[:-len(suffix)]
            if not field:
                return None
            return {"field": field, "operation": op, "value": _parse_value(value, op)}
    return {"field": key, "operation": "eq", "value": _parse_value(value, "eq")}


def _parse_url_filters(request: Request) -> list[dict[str, Any]]:
    filters: list[dict[str, Any]] = []
    for key, value in request.query_params.items():
        if key in RESERVED_QUERY_KEYS or value == "":
            continue
        parsed = _parse_filter_param(key, value)
        if parsed:
            filters.append(parsed)
    return filters


def _coerce_body_filters(body: Any) -> tuple[Optional[dict[str, Any]], list[dict[str, Any]]]:
    if body is None:
        return None, []
    if isinstance(body, list):
        return None, [item for item in body if isinstance(item, dict)]
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="Filter body must be an object or a list of filter objects.")
    if body.get("node_type"):
        return body, []
    tree = body.get("filter_tree") if isinstance(body.get("filter_tree"), dict) else None
    filters = body.get("filters") if isinstance(body.get("filters"), list) else []
    return tree, [item for item in filters if isinstance(item, dict)]


def _field_type(entity: dict[str, Any], field_name: str) -> str:
    flat = field_name.split(".")[-1]
    for field in entity.get("fields", []):
        if field.get("name") == flat:
            return str(field.get("type") or "string")
    return "string"


def _resolve_field(
    query: Any,
    root_model: type[Any],
    field_path: str,
    operation: Optional[str] = None,
    joins: Optional[dict[str, Any]] = None,
) -> tuple[Any, Any, bool]:
    parts = field_path.split(".")
    if not parts or any(not part for part in parts):
        raise HTTPException(status_code=400, detail=f"Invalid field path: {field_path}")

    current = root_model
    joined = False
    join_registry = joins if joins is not None else {}
    path_parts: list[str] = []

    for rel_name in parts[:-1]:
        path_parts.append(rel_name)
        relationship_path = ".".join(path_parts)
        if not hasattr(current, rel_name):
            current_name = getattr(current, "__name__", str(current))
            raise HTTPException(status_code=400, detail=f"Model '{current_name}' has no relationship '{rel_name}'.")
        rel_attr = getattr(current, rel_name)
        if not hasattr(rel_attr, "property") or not hasattr(rel_attr.property, "mapper"):
            current_name = getattr(current, "__name__", str(current))
            raise HTTPException(status_code=400, detail=f"Attribute '{rel_name}' on '{current_name}' is not a relationship.")
        related_alias = join_registry.get(relationship_path)
        if related_alias is None:
            related_alias = aliased(rel_attr.property.mapper.class_)
            query = query.outerjoin(related_alias, rel_attr)
            join_registry[relationship_path] = related_alias
            joined = True
        current = related_alias

    col_name = parts[-1]
    if not hasattr(current, col_name):
        current_name = getattr(current, "__name__", str(current))
        raise HTTPException(status_code=400, detail=f"Model '{current_name}' has no field '{col_name}'.")
    return getattr(current, col_name), query, joined


def _column_type(column: Any) -> Any:
    try:
        return column.property.columns[0].type
    except (AttributeError, IndexError):
        return None


def _invalid_value(field: str, value: Any, expected: str) -> HTTPException:
    return HTTPException(
        status_code=400,
        detail=f"Invalid value {value!r} for field '{field}'; expected {expected}.",
    )


def _coerce_scalar(column: Any, field: str, value: Any) -> Any:
    if value is None:
        return None
    type_obj = _column_type(column)
    try:
        if isinstance(type_obj, Boolean):
            if isinstance(value, bool):
                return value
            if isinstance(value, int) and value in {0, 1}:
                return bool(value)
            if isinstance(value, str):
                lowered = value.strip().lower()
                if lowered in {"true", "1", "yes", "on"}:
                    return True
                if lowered in {"false", "0", "no", "off"}:
                    return False
            raise _invalid_value(field, value, "a boolean")
        if isinstance(type_obj, Integer) and not isinstance(type_obj, Boolean):
            if isinstance(value, bool):
                raise _invalid_value(field, value, "an integer")
            return int(value)
        if isinstance(type_obj, (Float, Numeric)):
            if isinstance(value, bool):
                raise _invalid_value(field, value, "a number")
            return Decimal(str(value)) if isinstance(type_obj, Numeric) else float(value)
        if isinstance(type_obj, DateTime):
            if isinstance(value, datetime):
                return value
            if isinstance(value, str):
                return datetime.fromisoformat(value.replace("Z", "+00:00"))
            raise _invalid_value(field, value, "an ISO-8601 datetime")
        if isinstance(type_obj, Date):
            if isinstance(value, datetime):
                return value.date()
            if isinstance(value, date):
                return value
            if isinstance(value, str):
                return date.fromisoformat(value)
            raise _invalid_value(field, value, "an ISO-8601 date")
        if isinstance(type_obj, Enum):
            enum_class = getattr(type_obj, "enum_class", None)
            if enum_class is not None:
                if isinstance(value, enum_class):
                    return value
                for member in enum_class:
                    if value == member.name or value == member.value:
                        return member
            allowed = list(getattr(type_obj, "enums", []) or [])
            if value in allowed:
                return value
            raise HTTPException(
                status_code=400,
                detail=f"Invalid enum value {value!r} for field '{field}'. Allowed values: {allowed}.",
            )
        python_type = getattr(type_obj, "python_type", None)
        if python_type is UUID:
            return value if isinstance(value, UUID) else UUID(str(value))
        return value
    except HTTPException:
        raise
    except (TypeError, ValueError, ArithmeticError):
        raise _invalid_value(field, value, type(type_obj).__name__ or "the column type")


def _coerce_filter_value(column: Any, field: str, operation: str, value: Any) -> Any:
    if operation in {"is_null", "is_not_null"}:
        return None
    if isinstance(_column_type(column), Enum) and operation in {
        "like", "ilike", "starts_with", "ends_with"
    }:
        return str(value)
    if operation in {"in", "not_in", "between"}:
        if not isinstance(value, list):
            expected = "a list" if operation != "between" else "a two-value list"
            raise _invalid_value(field, value, expected)
        return [_coerce_scalar(column, field, item) for item in value]
    return _coerce_scalar(column, field, value)


def _filter_expression(column: Any, operation: str, value: Any) -> Any:
    comparison_column = column
    if isinstance(_column_type(column), Enum) and operation in {
        "like", "ilike", "starts_with", "ends_with"
    }:
        comparison_column = cast(column, String)
    if operation == "eq":
        return comparison_column == value
    if operation == "ne":
        return comparison_column != value
    if operation == "gt":
        return comparison_column > value
    if operation == "gte":
        return comparison_column >= value
    if operation == "lt":
        return comparison_column < value
    if operation == "lte":
        return comparison_column <= value
    if operation == "like":
        return comparison_column.like(f"%{value}%")
    if operation == "ilike":
        return comparison_column.ilike(f"%{value}%")
    if operation == "starts_with":
        return comparison_column.like(f"{value}%")
    if operation == "ends_with":
        return comparison_column.like(f"%{value}")
    if operation == "in":
        if not isinstance(value, list) or not value:
            raise HTTPException(status_code=400, detail="Operation 'in' requires a non-empty list value.")
        return column.in_(value)
    if operation == "not_in":
        if not isinstance(value, list) or not value:
            raise HTTPException(status_code=400, detail="Operation 'not_in' requires a non-empty list value.")
        return ~column.in_(value)
    if operation == "is_null":
        return column.is_(None)
    if operation == "is_not_null":
        return column.is_not(None)
    if operation == "between":
        if not isinstance(value, list) or len(value) != 2:
            raise HTTPException(status_code=400, detail="Operation 'between' requires exactly two values.")
        return column.between(value[0], value[1])
    raise HTTPException(status_code=400, detail=f"Unsupported filter operation: {operation}")


def _apply_filter(
    query: Any,
    model: type[Any],
    filter_rule: dict[str, Any],
    joins: Optional[dict[str, Any]] = None,
) -> tuple[Any, bool]:
    field = filter_rule.get("field")
    operation = filter_rule.get("operation", "eq")
    value = filter_rule.get("value")
    if not field or operation not in VALID_OPS:
        raise HTTPException(status_code=400, detail=f"Invalid filter rule: {filter_rule}")
    if operation not in {"is_null", "is_not_null"} and value in (None, "", []):
        return query, False
    column, query, joined = _resolve_field(
        query,
        model,
        str(field),
        str(operation),
        joins,
    )
    coerced = _coerce_filter_value(column, str(field), str(operation), value)
    return query.filter(_filter_expression(column, str(operation), coerced)), joined


def _evaluate_tree(
    query: Any,
    model: type[Any],
    node: dict[str, Any],
    depth: int = 0,
    joins: Optional[dict[str, Any]] = None,
) -> tuple[Any, Any, bool]:
    if depth > MAX_FILTER_TREE_DEPTH:
        raise HTTPException(status_code=400, detail=f"Filter tree exceeds maximum depth of {MAX_FILTER_TREE_DEPTH}.")
    node_type = node.get("node_type")
    if node_type == "condition":
        field = node.get("field")
        operation = node.get("operation")
        value = node.get("value")
        if not field or not operation:
            raise HTTPException(status_code=400, detail="Condition nodes require 'field' and 'operation'.")
        if operation not in {"is_null", "is_not_null"} and value in (None, "", []):
            return query, None, False
        column, query, joined = _resolve_field(
            query,
            model,
            str(field),
            str(operation),
            joins,
        )
        coerced = _coerce_filter_value(column, str(field), str(operation), value)
        return query, _filter_expression(column, str(operation), coerced), joined

    if node_type != "operator":
        raise HTTPException(status_code=400, detail="Filter node_type must be 'operator' or 'condition'.")

    operator = node.get("operator")
    children = node.get("children") or []
    if operator not in {"AND", "OR"} or not children:
        raise HTTPException(status_code=400, detail="Operator nodes require operator AND/OR and at least one child.")

    clauses = []
    any_joined = False
    for child in children:
        if not isinstance(child, dict):
            continue
        query, clause, joined = _evaluate_tree(
            query,
            model,
            child,
            depth + 1,
            joins,
        )
        any_joined = any_joined or joined
        if clause is not None:
            clauses.append(clause)

    if not clauses:
        return query, None, any_joined
    if len(clauses) == 1:
        return query, clauses[0], any_joined
    from sqlalchemy import and_, or_
    return query, (and_(*clauses) if operator == "AND" else or_(*clauses)), any_joined


def _apply_tree(
    query: Any,
    model: type[Any],
    tree: Optional[dict[str, Any]],
    joins: Optional[dict[str, Any]] = None,
) -> tuple[Any, bool]:
    if not tree:
        return query, False
    query, clause, joined = _evaluate_tree(query, model, tree, joins=joins)
    if clause is not None:
        query = query.filter(clause)
    return query, joined


def _searchable_fields(entity: dict[str, Any]) -> list[str]:
    return [
        str(field.get("name"))
        for field in entity.get("fields", [])
        if str(field.get("type")) in {"string", "text", "enum"}
    ]


def _apply_search(
    query: Any,
    model: type[Any],
    entity: dict[str, Any],
    search: Optional[str],
    joins: Optional[dict[str, Any]] = None,
) -> Any:
    if not search:
        return query
    clauses = []
    for field in _searchable_fields(entity):
        column, query, _ = _resolve_field(query, model, field, joins=joins)
        clauses.append(cast(column, String).ilike(f"%{search}%"))
    if clauses:
        query = query.filter(or_(*clauses))
    return query


def _default_sort_field(entity: dict[str, Any]) -> str:
    primary_keys = entity.get("primary_keys") or []
    if primary_keys:
        return str(primary_keys[0])
    fields = entity.get("fields") or []
    return str(fields[0].get("name") if fields else "id")


def _apply_sort(
    query: Any,
    model: type[Any],
    entity: dict[str, Any],
    sort_by: Optional[str],
    order: str,
    joins: Optional[dict[str, Any]] = None,
) -> Any:
    sort_field = sort_by or _default_sort_field(entity)
    column, query, _ = _resolve_field(query, model, sort_field, joins=joins)
    direction = desc if str(order).lower() == "desc" else asc
    return query.order_by(direction(column))


def _count_query(query: Any, model: type[Any]) -> int:
    primary_keys = sa_inspect(model).primary_key
    if primary_keys:
        return int(query.order_by(None).with_entities(func.count(func.distinct(primary_keys[0]))).scalar() or 0)
    return int(query.count() or 0)


def _json_value(value: Any) -> Any:
    if isinstance(value, (datetime, date)):
        return value.isoformat()
    if isinstance(value, Decimal):
        return float(value)
    return value


def _serialize_shallow(obj: Any) -> dict[str, Any]:
    mapper = sa_inspect(obj.__class__)
    return {column.key: _json_value(getattr(obj, column.key)) for column in mapper.columns}


def _serialize_row(obj: Any, entity: dict[str, Any]) -> dict[str, Any]:
    out = _serialize_shallow(obj)
    for rel in entity.get("relationships", []):
        if rel.get("uselist") or rel.get("cardinality") in {"o2m", "m2m"}:
            continue
        name = rel.get("name")
        if not name:
            continue
        try:
            related = getattr(obj, str(name))
        except Exception:
            continue
        out[str(name)] = None if related is None else _serialize_shallow(related)
    return out


def _page_meta(page: int, size: int, total: int) -> dict[str, int]:
    return {
        "page": page,
        "size": size,
        "total_items": total,
        "total_pages": ((total + size - 1) // size) if total else 0,
    }


def _run_query(
    db: Any,
    entity: dict[str, Any],
    model: type[Any],
    *,
    page: int,
    size: int,
    sort_by: Optional[str],
    order: str,
    search: Optional[str],
    filters: list[dict[str, Any]],
    filter_tree: Optional[dict[str, Any]],
    predicate_hooks: Iterable[Any],
    principal: Any,
    request: Request,
    action: str,
) -> dict[str, Any]:
    query = db.query(model)
    joins: dict[str, Any] = {}
    query = _apply_predicates(
        query,
        predicate_hooks=predicate_hooks,
        principal=principal,
        request=request,
        entity=entity,
        model=model,
        action=action,
    )
    for filter_rule in filters:
        query, _ = _apply_filter(query, model, filter_rule, joins)
    query, _ = _apply_tree(query, model, filter_tree, joins)
    query = _apply_search(query, model, entity, search, joins)
    total = _count_query(query, model)
    query = _apply_sort(query, model, entity, sort_by, order, joins)
    rows = query.offset((page - 1) * size).limit(size).all()
    return {
        "data": [_serialize_row(row, entity) for row in rows],
        "meta": _page_meta(page, size, total),
    }


def _csv_chunks(rows: Iterable[dict[str, Any]]) -> Iterator[bytes]:
    iterator = iter(rows)
    try:
        first = next(iterator)
    except StopIteration:
        yield b"/xef/xbb/xbf"
        return
    fields = list(first)
    buffer = io.StringIO(newline="")
    writer = csv.DictWriter(buffer, fieldnames=fields, extrasaction="ignore", lineterminator="/r/n")
    writer.writeheader()
    writer.writerow(first)
    yield b"/xef/xbb/xbf" + buffer.getvalue().encode("utf-8")
    for row in iterator:
        buffer.seek(0)
        buffer.truncate(0)
        writer.writerow(row)
        yield buffer.getvalue().encode("utf-8")


def _json_chunks(rows: Iterable[dict[str, Any]]) -> Iterator[bytes]:
    yield b"["
    first = True
    for row in rows:
        if not first:
            yield b","
        first = False
        yield json.dumps(row, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    yield b"]"


def _xlsx_chunks(rows: Iterable[dict[str, Any]]) -> Iterator[bytes]:
    with tempfile.SpooledTemporaryFile(max_size=1024 * 1024, mode="w+b") as output:
        with zipfile.ZipFile(output, "w", compression=zipfile.ZIP_DEFLATED, allowZip64=True) as workbook:
            workbook.writestr("[Content_Types].xml", '<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>')
            workbook.writestr("_rels/.rels", '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>')
            workbook.writestr("xl/workbook.xml", '<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Export" sheetId="1" r:id="rId1"/></sheets></workbook>')
            workbook.writestr("xl/_rels/workbook.xml.rels", '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>')
            with workbook.open("xl/worksheets/sheet1.xml", "w", force_zip64=True) as sheet:
                sheet.write(b'<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>')
                fields: list[str] = []
                row_number = 0
                for row in rows:
                    if not fields:
                        fields = list(row)
                        row_number += 1
                        cells = "".join(f'<c t="inlineStr"><is><t>{xml_escape(field)}</t></is></c>' for field in fields)
                        sheet.write(f'<row r="{row_number}">{cells}</row>'.encode("utf-8"))
                    row_number += 1
                    cells = "".join(f'<c t="inlineStr"><is><t>{xml_escape(json.dumps(row.get(field), ensure_ascii=False) if isinstance(row.get(field), (dict, list)) else str(row.get(field) if row.get(field) is not None else ""))}</t></is></c>' for field in fields)
                    sheet.write(f'<row r="{row_number}">{cells}</row>'.encode("utf-8"))
                sheet.write(b"</sheetData></worksheet>")
        output.seek(0)
        while chunk := output.read(64 * 1024):
            yield chunk


def _run_group_by(
    db: Any,
    entity: dict[str, Any],
    model: type[Any],
    *,
    field: str,
    search: Optional[str],
    filters: list[dict[str, Any]],
    filter_tree: Optional[dict[str, Any]],
    predicate_hooks: Iterable[Any],
    principal: Any,
    request: Request,
    action: str,
) -> list[dict[str, Any]]:
    query = db.query(model)
    joins: dict[str, Any] = {}
    query = _apply_predicates(
        query,
        predicate_hooks=predicate_hooks,
        principal=principal,
        request=request,
        entity=entity,
        model=model,
        action=action,
    )
    for filter_rule in filters:
        query, _ = _apply_filter(query, model, filter_rule, joins)
    query, _ = _apply_tree(query, model, filter_tree, joins)
    query = _apply_search(query, model, entity, search, joins)
    column, query, _ = _resolve_field(query, model, field, joins=joins)
    rows = query.with_entities(column, func.count().label("count")).group_by(column).order_by(func.count().desc()).all()
    return [{"key": _json_value(row[0]), "count": row[1]} for row in rows]


def create_router(
    api_prefix: str = "/api",
    entities: Optional[list[dict[str, Any]]] = None,
    session_dependency_import: str = "app.database:get_db",
    auth_dependency_import: Optional[str] = None,
    permission_hook_import: Optional[str] = None,
    global_predicate_hook_imports: Optional[list[str]] = None,
    entity_predicate_hook_imports: Optional[dict[str, list[str]]] = None,
) -> APIRouter:
    prefix = _normalize_prefix(api_prefix)
    entity_list = entities or []
    registry = _build_registry(entity_list)
    get_db = _import_object(session_dependency_import)
    auth_dependency = _import_object(auth_dependency_import) if auth_dependency_import else _anonymous_principal
    permission_hook = _import_object(permission_hook_import) if permission_hook_import else None
    global_predicate_hooks = [
        _import_object(path) for path in (global_predicate_hook_imports or [])
    ]
    entity_predicate_hooks = {
        entity_name: [_import_object(path) for path in paths]
        for entity_name, paths in (entity_predicate_hook_imports or {}).items()
    }

    def predicates_for(entity_meta: dict[str, Any]) -> list[Any]:
        model_name = str(entity_meta.get("model") or "")
        return [*global_predicate_hooks, *entity_predicate_hooks.get(model_name, [])]

    router = APIRouter(prefix=f"{prefix}/filterx", tags=["filterx"])

    @router.get("/metadata")
    def get_metadata(
        request: Request,
        principal: Any = Depends(auth_dependency),
    ) -> dict[str, object]:
        _authorize(
            permission_hook,
            principal=principal,
            request=request,
            entity=None,
            action="metadata.list",
        )
        return build_metadata()

    @router.get("/{entity}/metadata")
    def get_entity_metadata(
        entity: str,
        request: Request,
        principal: Any = Depends(auth_dependency),
    ) -> dict[str, Any]:
        entity_meta = _get_entity(registry, entity)
        _authorize(
            permission_hook,
            principal=principal,
            request=request,
            entity=entity_meta,
            action="metadata.read",
        )
        return entity_meta

    @router.get("/{entity}")
    @router.get("/{entity}/query")
    def query_entity(
        entity: str,
        request: Request,
        page: int = Query(1, ge=1),
        size: int = Query(20, ge=1, le=100),
        sort_by: Optional[str] = Query(None),
        order: str = Query("asc", pattern="^(asc|desc)$"),
        search: Optional[str] = Query(None),
        db: Any = Depends(get_db),
        principal: Any = Depends(auth_dependency),
    ) -> dict[str, Any]:
        entity_meta = _get_entity(registry, entity)
        _authorize(
            permission_hook,
            principal=principal,
            request=request,
            entity=entity_meta,
            action="query",
        )
        model = _model_for_entity(entity_meta)
        filters = _parse_url_filters(request)
        return _run_query(
            db,
            entity_meta,
            model,
            page=page,
            size=size,
            sort_by=sort_by,
            order=order,
            search=search,
            filters=filters,
            filter_tree=None,
            predicate_hooks=predicates_for(entity_meta),
            principal=principal,
            request=request,
            action="query",
        )

    @router.post("/{entity}/filter")
    def filter_entity(
        entity: str,
        request: Request,
        body: Any = Body(default=None),
        page: int = Query(1, ge=1),
        size: int = Query(20, ge=1, le=100),
        sort_by: Optional[str] = Query(None),
        order: str = Query("asc", pattern="^(asc|desc)$"),
        search: Optional[str] = Query(None),
        db: Any = Depends(get_db),
        principal: Any = Depends(auth_dependency),
    ) -> dict[str, Any]:
        entity_meta = _get_entity(registry, entity)
        _authorize(
            permission_hook,
            principal=principal,
            request=request,
            entity=entity_meta,
            action="filter",
        )
        model = _model_for_entity(entity_meta)
        tree, filters = _coerce_body_filters(body)
        return _run_query(
            db,
            entity_meta,
            model,
            page=page,
            size=size,
            sort_by=sort_by,
            order=order,
            search=search,
            filters=filters,
            filter_tree=tree,
            predicate_hooks=predicates_for(entity_meta),
            principal=principal,
            request=request,
            action="filter",
        )

    @router.post("/{entity}/export")
    def export_entity(
        entity: str,
        request: Request,
        body: Any = Body(default=None),
        format: str = Query("csv", pattern="^(csv|xlsx|json)$"),
        sort_by: Optional[str] = Query(None),
        order: str = Query("asc", pattern="^(asc|desc)$"),
        search: Optional[str] = Query(None),
        db: Any = Depends(get_db),
        principal: Any = Depends(auth_dependency),
    ) -> StreamingResponse:
        entity_meta = _get_entity(registry, entity)
        _authorize(permission_hook, principal=principal, request=request, entity=entity_meta, action="export")
        model = _model_for_entity(entity_meta)
        tree, filters = _coerce_body_filters(body)

        def rows() -> Iterator[dict[str, Any]]:
            page = 1
            while True:
                result = _run_query(
                    db,
                    entity_meta,
                    model,
                    page=page,
                    size=100,
                    sort_by=sort_by,
                    order=order,
                    search=search,
                    filters=filters,
                    filter_tree=tree,
                    predicate_hooks=predicates_for(entity_meta),
                    principal=principal,
                    request=request,
                    action="export",
                )
                yield from result["data"]
                if page >= result["meta"]["total_pages"]:
                    break
                page += 1

        filename = f"{entity}.{format}"
        headers = {"Content-Disposition": f'attachment; filename="{filename}"'}
        if format == "csv":
            return StreamingResponse(_csv_chunks(rows()), media_type="text/csv; charset=utf-8", headers=headers)
        if format == "xlsx":
            return StreamingResponse(_xlsx_chunks(rows()), media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", headers=headers)
        return StreamingResponse(_json_chunks(rows()), media_type="application/json; charset=utf-8", headers=headers)

    @router.get("/{entity}/group-by/{field:path}")
    def group_entity(
        entity: str,
        field: str,
        request: Request,
        search: Optional[str] = Query(None),
        db: Any = Depends(get_db),
        principal: Any = Depends(auth_dependency),
    ) -> list[dict[str, Any]]:
        entity_meta = _get_entity(registry, entity)
        _authorize(
            permission_hook,
            principal=principal,
            request=request,
            entity=entity_meta,
            action="group",
        )
        model = _model_for_entity(entity_meta)
        filters = _parse_url_filters(request)
        return _run_group_by(
            db,
            entity_meta,
            model,
            field=field,
            search=search,
            filters=filters,
            filter_tree=None,
            predicate_hooks=predicates_for(entity_meta),
            principal=principal,
            request=request,
            action="group",
        )

    @router.post("/{entity}/group-by/{field:path}/filter")
    def group_entity_with_filter(
        entity: str,
        field: str,
        request: Request,
        body: Any = Body(default=None),
        search: Optional[str] = Query(None),
        db: Any = Depends(get_db),
        principal: Any = Depends(auth_dependency),
    ) -> list[dict[str, Any]]:
        entity_meta = _get_entity(registry, entity)
        _authorize(
            permission_hook,
            principal=principal,
            request=request,
            entity=entity_meta,
            action="group.filter",
        )
        model = _model_for_entity(entity_meta)
        tree, filters = _coerce_body_filters(body)
        return _run_group_by(
            db,
            entity_meta,
            model,
            field=field,
            search=search,
            filters=filters,
            filter_tree=tree,
            predicate_hooks=predicates_for(entity_meta),
            principal=principal,
            request=request,
            action="group.filter",
        )

    return router

