  margin-top: 6px;
}

.search-option {
  margin: 0 6px;
  padding: 10px 12px;
  border-radius: 8px;
  color: var(--color-text);
}

.option-label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.option-prefix,
.option-suffix {
  color: var(--color-text-soft);
}

.option-field {
  display: inline-flex;
  padding: 1px 8px;
  border-radius: 999px;
  border: 1px solid #d4dee8;
